// ===== EDIT THESE =====
const TELEGRAM_CHAT_ID = 'PASTE_YOUR_TELEGRAM_CHAT_ID';
const pages = [
  { url: 'https://ismylmohammad.com/', title: 'Ismyl Mohammad | AI, Data & Automation Consulting', description: 'Services, sample projects and a free readiness check.' },
  { url: 'https://ismylmohammad.com/articles', title: 'Articles | Ismyl Mohammad', description: 'Practical guides on automation, data and AI.' }
];
// ======================

const pillars = [
  { service: 'n8n workflow automation', angle: 'removing repetitive manual work with automated workflows' },
  { service: 'AI and data governance', angle: 'using AI safely: policies, data ownership, risk and compliance' },
  { service: 'data engineering', angle: 'reliable data pipelines and getting data out of spreadsheets and silos' },
  { service: 'data analysis', angle: 'turning raw business data into decisions people actually act on' },
  { service: 'agentic AI and RAG', angle: 'AI agents and assistants grounded in a company\'s own documents and data' },
  { service: 'enterprise architecture', angle: 'connecting systems so tools, data and processes fit together' },
  { service: 'consulting and advisory', angle: 'how to scope, prioritise and start an AI or data project without wasting money' }
];
const audiences = [
  { name: 'small business owners and founders', pain: 'manual admin, scattered spreadsheets, slow follow-ups, too little time', tone: 'practical, plain English, zero jargon' },
  { name: 'data and AI leaders at mid-size and large companies', pain: 'AI risk and governance, messy pipelines, unclear data ownership, pilots that never reach production', tone: 'strategic, credible, specific' }
];
const formats = [
  'a practical how-to with 3 to 5 concrete steps',
  'a common mistake and how to avoid it',
  'myth vs reality',
  'a short checklist the reader can use today',
  'a before-and-after of a manual process vs an automated or well-designed one (clearly hypothetical)'
];

const s = $getWorkflowStaticData('global');
const count = s.count || 0;
s.count = count + 1;
const pillar = pillars[count % pillars.length];
const audience = audiences[count % audiences.length];
const format = formats[count % formats.length];
const page = pages[count % pages.length];
const recent = (s.recent || []).join(' | ') || 'none yet';

return [{ json: {
  telegramChatId: TELEGRAM_CHAT_ID,
  service: pillar.service, angle: pillar.angle,
  audience: audience.name, pain: audience.pain, tone: audience.tone,
  format, recentTopics: recent,
  linkUrl: page.url, linkTitle: page.title, linkDescription: page.description
} }];

